(async () => {
  const a=window.__CITY_APP, R=a.streetcarRide, car=R.car;
  if(!R.active) throw new Error('No featured ride');
  document.getElementById('locate-prompt').hidden=true;
  const original=R.car, start=car.stopIndex, stops=[];
  a.film.start(10);
  let requested=false;
  try {
    for(let batch=0;batch<360;batch++) {
      const elapsed=await a.film.step(25);
      if(batch%24===0) console.log('[ride-check] progress '+JSON.stringify({batch,s:car.s,speed:car.speed,doors:car.doorState,why:a.streetcars.whyWaiting(car,elapsed)}));
      if(!R.active || R.car!==original || !a.streetcars.cars.includes(original)) throw new Error('Occupied service identity lost');
      if(!requested && car.doorState==='closed') { R.action(); requested=true; console.log('[ride-check] requested next stop'); }
      if(car.doorState==='open' && car.stopIndex>start && !stops.includes(car.stopIndex)) {
        stops.push(car.stopIndex);
        console.log('[ride-check] arrived '+JSON.stringify({index:car.stopIndex,name:car.track.stopNames[car.stopIndex],s:car.s,simulationSeconds:(batch+1)*2.5}));
        if(stops.length===3) break;
      }
    }
    if(stops.length<3) throw new Error('Did not reach three stops: '+JSON.stringify({stops,s:car.s,speed:car.speed,k:car.k,doors:car.doorState}));
    for(let attempt=0;attempt<10&&!R.exitPoint(car);attempt++) { car.hold=3; await a.film.step(10); }
    if(!R.exitPoint(car)) throw new Error('No safe sidewalk exit at arrival');
    window.__rideArrival={x:a.controllerManager.getActiveEntity().position.x,z:a.controllerManager.getActiveEntity().position.z};
    if(!R.action()||R.active||a.controllerManager.suspended) throw new Error('Alighting failed');
    const p=a.controllerManager.getActiveEntity().position;
    if(!a.controllerManager.isPointOnSidewalk(p.x,p.z)||Math.abs(p.y-a.controllerManager.getGroundHeight(p.x,p.z))>.1) throw new Error('Invalid sidewalk landing');
    if(a.cameraSystem.followOverride||!a.controllerManager.getActiveEntity().mesh.visible) throw new Error('Failed to restore camera/model');
    console.log('[ride-check] alighted safely '+JSON.stringify({x:p.x,y:p.y,z:p.z,stops:stops.length}));
  } finally { a.film.stop(); }
})()

(() => {
  // pagehide (main.js) saves the safe boarding position, not the seat, then ends the ride through the shared
  // cancellation (docs/experience-coordination.md), so it runs on the night ride, after the journey. A back-forward
  // cache hide, so the page carries on as if restored.
  const a=window.__CITY_APP, R=a.streetcarRide, cm=a.controllerManager;
  if(!R.active) throw new Error('No night ride to hide the page on');
  const safe=a.rideSession.savedGround(cm.activeMode);
  if(!safe) throw new Error('No safe ground while riding');
  window.dispatchEvent(new PageTransitionEvent('pagehide',{persisted:true}));
  const saved=JSON.parse(localStorage.getItem('toronto-player-state'));
  if(Math.hypot(saved.entities[saved.activeMode].x-safe.x,saved.entities[saved.activeMode].z-safe.z)>0.01) throw new Error('Saved seat instead of safe ground');
  console.log('[ride-check] persistence uses safe boarding position');
  if(R.active||a.rideSession.active||cm.suspended||a.cameraSystem.followOverride||!cm.getActiveEntity().mesh.visible) throw new Error('pagehide did not end the ride');
  const p=cm.getActiveEntity().position;
  if(Math.hypot(p.x-safe.x,p.z-safe.z)>0.05) throw new Error('pagehide did not return the rider to safe ground: '+JSON.stringify({p,safe}));
  window.dispatchEvent(new PageTransitionEvent('pageshow',{persisted:true}));
  console.log('[ride-check] pagehide ends the ride at the safe boarding position');
})()
